export function mergeShoppingItems(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }

  const merged = new Map();

  for (const item of items) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      throw new TypeError('each item must be a non-null, non-array object');
    }

    const { name, quantity } = item;

    if (typeof name !== 'string' || name.trim() === '') {
      throw new TypeError('name must be a non-empty string');
    }

    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new TypeError('quantity must be a positive safe integer');
    }

    const trimmedName = name.trim();
    const key = trimmedName.toLowerCase();

    if (merged.has(key)) {
      const existing = merged.get(key);
      const nextQuantity = existing.quantity + quantity;
      if (!Number.isSafeInteger(nextQuantity)) {
        throw new RangeError('merged quantity exceeds safe integer range');
      }
      existing.quantity = nextQuantity;
    } else {
      merged.set(key, { name: trimmedName, quantity });
    }
  }

  return Array.from(merged.values(), (entry) => ({
    name: entry.name,
    quantity: entry.quantity,
  }));
}
